#!/usr/bin/env node
/**
 * Generates TypeScript types, metadata, resource classes, typed plugin examples,
 * and plugin reference documentation from recorded Kong Admin API schemas.
 *
 * Usage:
 *   node scripts/generate.mjs          # write generated files
 *   node scripts/generate.mjs --check  # verify committed files are up to date
 */

import { mkdir, readdir, readFile, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import prettier from 'prettier';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, '..');

const TARGET_39 = 'kong-3.9';
const TARGET_314 = 'kong-gateway-3.14';
const LABEL_39 = 'Kong 3.9';
const LABEL_314 = 'Kong Gateway 3.14';

const GENERATED_BANNER = '// Code generated by scripts/generate.mjs. DO NOT EDIT.\n\n';
const IDENTIFIER_RE = /^[A-Za-z_$][A-Za-z0-9_$]*$/;

/**
 * Input fields accepted by Kong's Admin API that are not listed in GET /schemas/<entity>.
 * Verified against both Kong 3.9 and Kong Gateway 3.14.
 */
const ENTITY_INPUT_OVERRIDES = {
  services: {
    makeOptional: new Set(['host']),
    extraFields: [
      {
        name: 'url',
        type: 'string',
        optional: true,
        nullable: false,
        jsdocLines: [
          'Shorthand URL to set protocol, host, port, and path together (for example `https://example.com:8443/api`).',
        ],
      },
    ],
  },
};

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function stableStringify(value) {
  if (Array.isArray(value)) {
    return `[${value.map(stableStringify).join(',')}]`;
  }
  if (isPlainObject(value)) {
    const entries = Object.keys(value)
      .sort()
      .map((k) => `${JSON.stringify(k)}:${stableStringify(value[k])}`);
    return `{${entries.join(',')}}`;
  }
  return JSON.stringify(value);
}

function escapeJsDoc(text) {
  return String(text).replaceAll('*/', '*\\/').replaceAll('\r\n', '\n').trim();
}

function resolvePluginRelativeLinks(text, pluginName) {
  if (!pluginName || typeof text !== 'string') {
    return text;
  }
  return text.replace(/\]\(#[^)]*\)/g, `](https://developer.konghq.com/plugins/${pluginName}/)`);
}

function formatPropName(name) {
  return IDENTIFIER_RE.test(name) ? name : JSON.stringify(name);
}

function formatLiteral(value) {
  if (typeof value === 'string') {
    return `'${value.replaceAll('\\', '\\\\').replaceAll("'", "\\'")}'`;
  }
  return String(value);
}

function formatDefaultValue(value) {
  if (typeof value === 'string') {
    return escapeJsDoc(formatLiteral(value));
  }
  return escapeJsDoc(JSON.stringify(value));
}

function formatJsDoc(lines, indent = '') {
  const cleaned = [];
  for (const raw of lines) {
    const text = escapeJsDoc(raw);
    if (!text) {
      continue;
    }
    for (const subline of text.split('\n')) {
      cleaned.push(subline.trimEnd());
    }
  }
  if (cleaned.length === 0) {
    return '';
  }
  if (cleaned.length === 1) {
    return `${indent}/** ${cleaned[0]} */\n`;
  }
  const body = cleaned.map((line) => (line ? `${indent} * ${line}` : `${indent} *`)).join('\n');
  return `${indent}/**\n${body}\n${indent} */\n`;
}

function capitalize(str) {
  return str ? str[0].toUpperCase() + str.slice(1) : '';
}

function lowerCamel(str) {
  return str ? str[0].toLowerCase() + str.slice(1) : '';
}

function slugifyCategory(category) {
  return category
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function pluginConfigInterfaceName(pluginName) {
  return pluginName.split('-').map(capitalize).join('') + 'Config';
}

function resourceClassName(resourceKey) {
  return `${capitalize(resourceKey)}Resource`;
}

function fieldsArrayToMap(fieldsList) {
  const map = new Map();
  for (const entry of fieldsList ?? []) {
    if (!isPlainObject(entry)) {
      continue;
    }
    for (const [name, def] of Object.entries(entry)) {
      map.set(name, def);
    }
  }
  return map;
}

function mergeFieldMaps(list39, list314) {
  const map39 = fieldsArrayToMap(list39);
  const map314 = fieldsArrayToMap(list314);
  const merged = [];
  for (const [name, def39] of map39.entries()) {
    merged.push({ name, def39, def314: map314.get(name) });
  }
  for (const [name, def314] of map314.entries()) {
    if (!map39.has(name)) {
      merged.push({ name, def39: undefined, def314 });
    }
  }
  return merged;
}

function hasNonNullDefault(def) {
  return def !== undefined && 'default' in def && def.default !== undefined && def.default !== null;
}

function mergeOneOf(oneOf39, oneOf314) {
  const a = Array.isArray(oneOf39) ? oneOf39 : undefined;
  const b = Array.isArray(oneOf314) ? oneOf314 : undefined;
  if (!a && !b) {
    return null;
  }
  if (a && !b) {
    return { values: [...a], only39: [], only314: [] };
  }
  if (!a && b) {
    return { values: [...b], only39: [], only314: [] };
  }
  const setA = new Set(a);
  const setB = new Set(b);
  const values = [...a, ...b.filter((v) => !setA.has(v))];
  const only39 = a.filter((v) => !setB.has(v));
  const only314 = b.filter((v) => !setA.has(v));
  return { values, only39, only314 };
}

function isRequiredEverywhere(def39, def314) {
  if (def39 && def314) {
    return def39.required === true && def314.required === true;
  }
  const sole = def39 ?? def314;
  return sole?.required === true;
}

function isAutoEverywhere(def39, def314) {
  if (def39 && def314) {
    return def39.auto === true && def314.auto === true;
  }
  const sole = def39 ?? def314;
  return sole?.auto === true;
}

function isAbstractOrEmptyRecord(def) {
  if (!def) {
    return true;
  }
  return def.abstract === true || !Array.isArray(def.fields) || def.fields.length === 0;
}

/**
 * Determines whether a field is required in an accepted (input/config) payload.
 *
 * A field is required only when:
 * - it exists in both targets (or in the sole target if inside a single-target record)
 * - `required` is true wherever it exists
 * - it has no non-null `default` in either target
 * - it is not `auto` in either target
 * - if it is a concrete `record`, at least one of its subfields is itself required
 *   (Kong auto-populates records whose subfields all have defaults or are optional).
 */
function isRequiredInInput(def39, def314, insideSingleTarget = false) {
  const presentInBoth = def39 !== undefined && def314 !== undefined;
  if (!insideSingleTarget && !presentInBoth) {
    return false;
  }
  if (!isRequiredEverywhere(def39, def314)) {
    return false;
  }
  if (hasNonNullDefault(def39) || hasNonNullDefault(def314)) {
    return false;
  }
  if (def39?.auto === true || def314?.auto === true) {
    return false;
  }

  const type39 = def39?.type;
  const type314 = def314?.type;
  const isRecord =
    (type39 === undefined || type39 === 'record') &&
    (type314 === undefined || type314 === 'record');
  if (isRecord) {
    if (isAbstractOrEmptyRecord(def39) && isAbstractOrEmptyRecord(def314)) {
      return false;
    }
    const subFields = mergeFieldMaps(def39?.fields, def314?.fields);
    return subFields.some((sub) =>
      isRequiredInInput(sub.def39, sub.def314, insideSingleTarget || !presentInBoth),
    );
  }
  return true;
}

function collectNestedOneOfNotes(def39, def314, notes) {
  const merged = mergeOneOf(def39?.one_of, def314?.one_of);
  if (merged) {
    if (merged.only39.length > 0) {
      notes.push(
        `${LABEL_39} only values: ${merged.only39.map((v) => `\`${formatLiteral(v)}\``).join(', ')}.`,
      );
    }
    if (merged.only314.length > 0) {
      notes.push(
        `${LABEL_314} only values: ${merged.only314.map((v) => `\`${formatLiteral(v)}\``).join(', ')}.`,
      );
    }
  }
  if (def39?.elements || def314?.elements) {
    collectNestedOneOfNotes(def39?.elements, def314?.elements, notes);
  }
}

function buildFieldJsDocLines(def39, def314, options = {}) {
  const { isShorthand = false, suppressTargetNote = false, pluginName = undefined } = options;
  const lines = [];

  if (def39?.description) {
    lines.push(resolvePluginRelativeLinks(def39.description, pluginName));
  }

  if (!suppressTargetNote) {
    if (def39 && !def314) {
      lines.push(`${LABEL_39} only.`);
    } else if (!def39 && def314) {
      lines.push(`${LABEL_314} only.`);
    }
  }

  if (def39 && def314 && def39.type && def314.type && def39.type !== def314.type) {
    lines.push(
      `Type differs between targets: ${LABEL_39} uses \`${def39.type}\`; ${LABEL_314} uses \`${def314.type}\`.`,
    );
  }

  collectNestedOneOfNotes(def39, def314, lines);

  const hasDef39 = hasNonNullDefault(def39);
  const hasDef314 = hasNonNullDefault(def314);
  if (def39 && def314) {
    if (hasDef39 && hasDef314) {
      const s39 = stableStringify(def39.default);
      const s314 = stableStringify(def314.default);
      if (s39 === s314) {
        lines.push(`@default ${formatDefaultValue(def39.default)}`);
      } else {
        lines.push(
          `@default ${LABEL_39}: ${formatDefaultValue(def39.default)}; ${LABEL_314}: ${formatDefaultValue(def314.default)}`,
        );
      }
    } else if (hasDef39) {
      lines.push(`@default ${LABEL_39}: ${formatDefaultValue(def39.default)}; ${LABEL_314}: none`);
    } else if (hasDef314) {
      lines.push(`@default ${LABEL_39}: none; ${LABEL_314}: ${formatDefaultValue(def314.default)}`);
    }
  } else if (hasDef39) {
    lines.push(`@default ${formatDefaultValue(def39.default)}`);
  } else if (hasDef314) {
    lines.push(`@default ${formatDefaultValue(def314.default)}`);
  }

  if (def39?.deprecation) {
    const dep = def39.deprecation;
    if (isPlainObject(dep) && typeof dep.message === 'string' && dep.message.trim()) {
      lines.push(`@deprecated ${resolvePluginRelativeLinks(dep.message.trim(), pluginName)}`);
    } else {
      lines.push('@deprecated');
    }
  } else if (isShorthand && def39?.description?.toLowerCase().includes('deprecated')) {
    lines.push('@deprecated');
  }

  return lines;
}

function renderForeignAcceptedType(reference, entityContext) {
  const variants = ['{ id: string }'];
  if (reference === 'consumers') {
    variants.push('{ username: string }');
  } else if (reference && entityContext.uniqueNameEntities.has(reference)) {
    variants.push('{ name: string }');
  }
  return variants.join(' | ');
}

function renderSingleType(def39, def314, mode, insideSingleTarget, entityContext, pluginName) {
  const sole = def39 ?? def314;
  const kongType = sole.type;

  switch (kongType) {
    case 'string': {
      const merged = mergeOneOf(def39?.one_of, def314?.one_of);
      if (merged && merged.values.length > 0) {
        return merged.values.map(formatLiteral).join(' | ');
      }
      return 'string';
    }
    case 'integer':
    case 'number': {
      const merged = mergeOneOf(def39?.one_of, def314?.one_of);
      if (merged && merged.values.length > 0) {
        return merged.values.map(formatLiteral).join(' | ');
      }
      return 'number';
    }
    case 'boolean':
      return 'boolean';
    case 'array':
    case 'set': {
      const elem39 = def39?.elements;
      const elem314 = def314?.elements;
      if (!elem39 && !elem314) {
        return 'Array<unknown>';
      }
      const elemType = renderType(
        elem39,
        elem314,
        mode,
        insideSingleTarget,
        entityContext,
        pluginName,
      );
      return `Array<${elemType}>`;
    }
    case 'map': {
      const val39 = def39?.values;
      const val314 = def314?.values;
      if (!val39 && !val314) {
        return 'Record<string, unknown>';
      }
      const valType = renderType(
        val39,
        val314,
        mode,
        insideSingleTarget,
        entityContext,
        pluginName,
      );
      return `Record<string, ${valType}>`;
    }
    case 'foreign': {
      if (mode === 'returned') {
        return '{ id: string }';
      }
      const ref = def39?.reference ?? def314?.reference;
      return renderForeignAcceptedType(ref, entityContext);
    }
    case 'json':
      return 'unknown';
    case 'record': {
      if (isAbstractOrEmptyRecord(def39) && isAbstractOrEmptyRecord(def314)) {
        return 'Record<string, unknown>';
      }
      const body = renderRecordMembers(def39, def314, mode, insideSingleTarget, entityContext, {
        pluginName,
      });
      return `{\n${body}}`;
    }
    default:
      return 'unknown';
  }
}

function renderType(def39, def314, mode, insideSingleTarget, entityContext, pluginName) {
  const type39 = def39?.type;
  const type314 = def314?.type;
  if (type39 && type314 && type39 !== type314) {
    const t39 = renderSingleType(def39, undefined, mode, true, entityContext, pluginName);
    const t314 = renderSingleType(undefined, def314, mode, true, entityContext, pluginName);
    return t39 === t314 ? t39 : `${t39} | ${t314}`;
  }
  return renderSingleType(def39, def314, mode, insideSingleTarget, entityContext, pluginName);
}

function withNullable(tsType) {
  if (tsType === 'unknown' || tsType.endsWith('| null')) {
    return tsType;
  }
  return `${tsType} | null`;
}

function renderRecordMembers(rec39, rec314, mode, insideSingleTarget, entityContext, options = {}) {
  const { entityName = undefined, isTopLevelEntity = false, pluginName = undefined } = options;
  const overrides =
    isTopLevelEntity && mode === 'accepted' ? ENTITY_INPUT_OVERRIDES[entityName] : undefined;
  const parentSingleTarget = insideSingleTarget || rec39 === undefined || rec314 === undefined;

  const lines = [];
  const regularFields = mergeFieldMaps(rec39?.fields, rec314?.fields);
  const regularNames = new Set(regularFields.map((f) => f.name));

  for (const { name, def39, def314 } of regularFields) {
    if (
      isTopLevelEntity &&
      mode === 'accepted' &&
      (name === 'created_at' || name === 'updated_at')
    ) {
      continue;
    }

    const fieldSingleTarget = parentSingleTarget || def39 === undefined || def314 === undefined;
    const jsdocLines = buildFieldJsDocLines(def39, def314, {
      suppressTargetNote: parentSingleTarget,
      pluginName,
    });
    const jsdoc = formatJsDoc(jsdocLines);

    // Special generic handling for the `plugins` entity's `name` and `config` fields.
    if (isTopLevelEntity && entityName === 'plugins' && name === 'name') {
      lines.push(`${jsdoc}${formatPropName(name)}: N;`);
      continue;
    }
    if (isTopLevelEntity && entityName === 'plugins' && name === 'config') {
      if (mode === 'returned') {
        lines.push(`${jsdoc}${formatPropName(name)}: ConfigOf<N>;`);
      } else {
        lines.push(`${jsdoc}${formatPropName(name)}?: ConfigOf<N> | null;`);
      }
      continue;
    }

    const tsType = renderType(def39, def314, mode, fieldSingleTarget, entityContext, pluginName);

    if (mode === 'returned') {
      const onlyInOneTarget = !parentSingleTarget && (def39 === undefined || def314 === undefined);
      const nonNull = isRequiredEverywhere(def39, def314) || isAutoEverywhere(def39, def314);
      const finalType = nonNull ? tsType : withNullable(tsType);
      const opt = onlyInOneTarget ? '?' : '';
      lines.push(`${jsdoc}${formatPropName(name)}${opt}: ${finalType};`);
    } else {
      const forcedOptional =
        (isTopLevelEntity && name === 'id') || Boolean(overrides?.makeOptional?.has(name));
      const required = !forcedOptional && isRequiredInInput(def39, def314, parentSingleTarget);
      if (required) {
        lines.push(`${jsdoc}${formatPropName(name)}: ${tsType};`);
      } else {
        lines.push(`${jsdoc}${formatPropName(name)}?: ${withNullable(tsType)};`);
      }
    }
  }

  if (overrides?.extraFields) {
    for (const extra of overrides.extraFields) {
      const jsdoc = formatJsDoc(extra.jsdocLines);
      const opt = extra.optional ? '?' : '';
      const finalType = extra.nullable ? withNullable(extra.type) : extra.type;
      lines.push(`${jsdoc}${formatPropName(extra.name)}${opt}: ${finalType};`);
    }
  }

  const shorthandFields = mergeFieldMaps(rec39?.shorthand_fields, rec314?.shorthand_fields);
  for (const { name, def39, def314 } of shorthandFields) {
    if (regularNames.has(name)) {
      continue;
    }
    const fieldSingleTarget = parentSingleTarget || def39 === undefined || def314 === undefined;
    const jsdocLines = buildFieldJsDocLines(def39, def314, {
      isShorthand: true,
      suppressTargetNote: parentSingleTarget,
      pluginName,
    });
    const jsdoc = formatJsDoc(jsdocLines);
    const tsType = renderType(def39, def314, mode, fieldSingleTarget, entityContext, pluginName);
    lines.push(`${jsdoc}${formatPropName(name)}?: ${withNullable(tsType)};`);
  }

  return lines.join('\n') + (lines.length > 0 ? '\n' : '');
}

async function readJson(filePath) {
  return JSON.parse(await readFile(filePath, 'utf8'));
}

async function readJsonIfExists(filePath) {
  try {
    return await readJson(filePath);
  } catch (err) {
    if (err && typeof err === 'object' && 'code' in err && err.code === 'ENOENT') {
      return undefined;
    }
    throw err;
  }
}

async function listJsonNames(dirPath) {
  const entries = await readdir(dirPath);
  return entries
    .filter((file) => file.endsWith('.json'))
    .map((file) => file.slice(0, -'.json'.length))
    .sort();
}

async function listFilesRecursive(dirPath, prefix = '') {
  let entries;
  try {
    entries = await readdir(dirPath, { withFileTypes: true });
  } catch (err) {
    if (err && typeof err === 'object' && 'code' in err && err.code === 'ENOENT') {
      return [];
    }
    throw err;
  }
  const files = [];
  for (const entry of entries) {
    const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
    if (entry.isDirectory()) {
      files.push(...(await listFilesRecursive(path.join(dirPath, entry.name), rel)));
    } else if (entry.isFile()) {
      files.push(rel);
    }
  }
  return files.sort();
}

async function loadEntityContext(resourcesJson) {
  const dir39 = path.join(REPO_ROOT, 'schemas', TARGET_39, 'entities');
  const dir314 = path.join(REPO_ROOT, 'schemas', TARGET_314, 'entities');

  const entityNames = new Set([
    ...(await listJsonNames(dir39)),
    ...(await listJsonNames(dir314)),
    ...Object.values(resourcesJson.resources).map((r) => r.entity),
  ]);

  const schemas39 = new Map();
  const schemas314 = new Map();
  const uniqueNameEntities = new Set();

  for (const entity of [...entityNames].sort()) {
    const s39 = await readJsonIfExists(path.join(dir39, `${entity}.json`));
    const s314 = await readJsonIfExists(path.join(dir314, `${entity}.json`));
    if (s39) {
      schemas39.set(entity, s39);
    }
    if (s314) {
      schemas314.set(entity, s314);
    }
    if (!s39 && !s314) {
      continue;
    }

    // Read `unique` from the kong-3.9 recording (structure-only 3.14 omits `unique`).
    const name39 = s39 ? fieldsArrayToMap(s39.fields).get('name') : undefined;
    if (name39?.unique === true) {
      uniqueNameEntities.add(entity);
    }
  }

  return { schemas39, schemas314, uniqueNameEntities };
}

function extractPluginScopes(schema39, schema314) {
  const fields39 = fieldsArrayToMap(schema39?.fields);
  const fields314 = fieldsArrayToMap(schema314?.fields);
  const scopes = ['global', 'service', 'route', 'consumer'];
  for (const scope of ['service', 'route', 'consumer']) {
    const f39 = fields39.get(scope);
    const f314 = fields314.get(scope);
    const pinnedNull39 = f39 !== undefined && 'eq' in f39 && f39.eq === null;
    const pinnedNull314 = f314 !== undefined && 'eq' in f314 && f314.eq === null;
    if (pinnedNull39 || pinnedNull314) {
      const idx = scopes.indexOf(scope);
      if (idx !== -1) {
        scopes.splice(idx, 1);
      }
    }
  }
  return scopes;
}

function extractPluginProtocols(schema39, schema314) {
  const p39 = fieldsArrayToMap(schema39?.fields).get('protocols')?.elements?.one_of ?? [];
  const p314 = fieldsArrayToMap(schema314?.fields).get('protocols')?.elements?.one_of ?? [];
  const merged = mergeOneOf(p39, p314);
  return merged ? merged.values : [];
}

function findForeignFieldsReferencing(childEntity, parentEntity, entityContext) {
  const s39 = entityContext.schemas39.get(childEntity);
  const s314 = entityContext.schemas314.get(childEntity);
  const merged = mergeFieldMaps(s39?.fields, s314?.fields);
  const matches = [];
  for (const { name, def39, def314 } of merged) {
    const def = def39 ?? def314;
    if (def?.type === 'foreign' && def.reference === parentEntity) {
      matches.push(name);
    }
  }
  return matches;
}

async function loadPluginRecords() {
  const categoriesJson = await readJson(path.join(REPO_ROOT, 'schemas', 'plugin-categories.json'));
  const dir39 = path.join(REPO_ROOT, 'schemas', TARGET_39, 'plugins');
  const dir314 = path.join(REPO_ROOT, 'schemas', TARGET_314, 'plugins');

  const names39 = await listJsonNames(dir39);
  const names314Set = new Set(await listJsonNames(dir314));
  const pluginNames = [...new Set([...names39, ...names314Set])].sort();

  const records = [];
  for (const name of pluginNames) {
    const schema39 = await readJsonIfExists(path.join(dir39, `${name}.json`));
    const schema314 = await readJsonIfExists(path.join(dir314, `${name}.json`));
    const meta = categoriesJson.plugins[name];
    if (!meta) {
      throw new Error(`Plugin "${name}" is missing from schemas/plugin-categories.json`);
    }
    const targets = [];
    if (schema39) {
      targets.push(TARGET_39);
    }
    if (schema314) {
      targets.push(TARGET_314);
    }
    records.push({
      name,
      category: meta.category,
      categorySlug: slugifyCategory(meta.category),
      title: meta.title,
      targets,
      scopes: extractPluginScopes(schema39, schema314),
      protocols: extractPluginProtocols(schema39, schema314),
      config39: fieldsArrayToMap(schema39?.fields).get('config'),
      config314: fieldsArrayToMap(schema314?.fields).get('config'),
    });
  }

  return records;
}

function generatePluginsSource(pluginRecords, entityContext) {
  const chunks = [GENERATED_BANNER];
  const configMapEntries = [];
  const pluginsMetadataEntries = [];

  for (const plugin of pluginRecords) {
    const ifaceName = pluginConfigInterfaceName(plugin.name);
    const members = renderRecordMembers(
      plugin.config39,
      plugin.config314,
      'accepted',
      false,
      entityContext,
      { pluginName: plugin.name },
    );
    const ifaceDoc = formatJsDoc([
      `Configuration for the \`${plugin.name}\` (${plugin.title}) plugin.`,
    ]);
    chunks.push(`${ifaceDoc}export interface ${ifaceName} {\n${members}}\n`);

    configMapEntries.push(`${formatPropName(plugin.name)}: ${ifaceName};`);

    pluginsMetadataEntries.push(
      `${formatPropName(plugin.name)}: {\n` +
        `category: ${formatLiteral(plugin.category)},\n` +
        `title: ${formatLiteral(plugin.title)},\n` +
        `targets: [${plugin.targets.map(formatLiteral).join(', ')}],\n` +
        `scopes: [${plugin.scopes.map(formatLiteral).join(', ')}],\n` +
        `protocols: [${plugin.protocols.map(formatLiteral).join(', ')}],\n` +
        `},`,
    );
  }

  chunks.push(
    formatJsDoc(['Mapping from first-class Kong plugin name to its configuration type.']) +
      `export interface PluginConfigs {\n${configMapEntries.join('\n')}\n}\n`,
  );

  chunks.push(
    formatJsDoc(['Union of all first-class Kong plugin names.']) +
      'export type PluginName = keyof PluginConfigs;\n',
  );

  chunks.push(
    formatJsDoc([
      'Configuration type for plugin `N`, falling back to `Record<string, unknown>` for custom plugins.',
    ]) +
      'export type ConfigOf<N extends string> = N extends PluginName ? PluginConfigs[N] : Record<string, unknown>;\n',
  );

  chunks.push(
    formatJsDoc(['Scope at which a Kong plugin can be attached.']) +
      "export type PluginScopeName = 'global' | 'service' | 'route' | 'consumer';\n",
  );

  chunks.push(
    formatJsDoc(['Metadata describing a first-class Kong plugin.']) +
      'export interface PluginInfo {\n' +
      '/** Plugin category. */\nreadonly category: string;\n' +
      '/** Human-readable plugin title. */\nreadonly title: string;\n' +
      '/** Recorded Kong targets that include this plugin. */\nreadonly targets: readonly string[];\n' +
      '/** Scopes at which the plugin can be attached. */\nreadonly scopes: readonly PluginScopeName[];\n' +
      '/** Protocols supported by the plugin across recorded targets. */\nreadonly protocols: readonly string[];\n' +
      '}\n',
  );

  chunks.push(
    formatJsDoc(['Metadata for every first-class Kong plugin, keyed by plugin name.']) +
      `export const PLUGINS: Readonly<Record<PluginName, PluginInfo>> = {\n${pluginsMetadataEntries.join('\n')}\n};\n`,
  );

  return chunks.join('\n');
}

function generateEntitiesSource(resourcesJson, entityContext) {
  const chunks = [GENERATED_BANNER, "import type { ConfigOf } from './plugins.js';\n"];

  for (const resource of Object.values(resourcesJson.resources)) {
    const { entity, type: typeName } = resource;
    const schema39 = entityContext.schemas39.get(entity);
    const schema314 = entityContext.schemas314.get(entity);
    if (!schema39 && !schema314) {
      throw new Error(`Missing recorded entity schema for "${entity}"`);
    }

    const isPlugin = entity === 'plugins';
    const genericClause = isPlugin ? '<N extends string = string>' : '';

    const returnedMembers = renderRecordMembers(
      schema39,
      schema314,
      'returned',
      false,
      entityContext,
      {
        entityName: entity,
        isTopLevelEntity: true,
      },
    );
    const returnedDoc = formatJsDoc([`Kong \`${entity}\` entity returned by the Admin API.`]);
    chunks.push(
      `${returnedDoc}export interface ${typeName}${genericClause} {\n${returnedMembers}}\n`,
    );

    const acceptedMembers = renderRecordMembers(
      schema39,
      schema314,
      'accepted',
      false,
      entityContext,
      {
        entityName: entity,
        isTopLevelEntity: true,
      },
    );
    const acceptedDoc = formatJsDoc([
      `Input payload accepted by Kong when creating or updating a \`${entity}\` entity.`,
    ]);
    chunks.push(
      `${acceptedDoc}export interface ${typeName}Input${genericClause} {\n${acceptedMembers}}\n`,
    );
  }

  return chunks.join('\n');
}

function generateResourcesSource(resourcesJson, entityContext) {
  const resources = resourcesJson.resources;
  const importedEntityTypes = new Set();
  const customClassImports = new Map();
  let usesCollection = false;
  let usesSingleton = false;
  let usesSegment = false;

  const templates = [];
  const classBlocks = [];
  const kongResourcesProps = [];
  const kongResourcesInits = [];

  function registerCustomClass(collectionClass) {
    let names = customClassImports.get(collectionClass.module);
    if (!names) {
      names = new Set();
      customClassImports.set(collectionClass.module, names);
    }
    names.add(collectionClass.name);
  }

  for (const [resourceKey, def] of Object.entries(resources)) {
    if (def.topLevel === false) {
      continue;
    }

    templates.push(`/${def.path}`, `/${def.path}/{}`);

    const className = resourceClassName(resourceKey);
    const paramName = lowerCamel(def.type);

    let extendsClause;
    if (def.collectionClass) {
      registerCustomClass(def.collectionClass);
      extendsClause = def.collectionClass.name;
    } else {
      usesCollection = true;
      importedEntityTypes.add(def.type);
      importedEntityTypes.add(`${def.type}Input`);
      extendsClause = `Collection<${def.type}, ${def.type}Input>`;
    }

    const methods = [];

    for (const [methodName, nested] of Object.entries(def.nested ?? {})) {
      const child = resources[nested.resource];
      if (!child) {
        throw new Error(`Unknown nested resource "${nested.resource}" on "${resourceKey}"`);
      }
      templates.push(`/${def.path}/{}/${nested.path}`, `/${def.path}/{}/${nested.path}/{}`);
      usesSegment = true;

      const routeTemplate = `/${def.path}/{${paramName}}/${nested.path}`;
      const pathExpr = `\`/${def.path}/\${segment(${paramName})}/${nested.path}\``;
      const doc = formatJsDoc([`Nested \`${nested.path}\` collection: \`${routeTemplate}\`.`]);

      if (child.collectionClass) {
        registerCustomClass(child.collectionClass);
        methods.push(
          `${doc}${methodName}(${paramName}: string): ${child.collectionClass.name} {\n` +
            `return new ${child.collectionClass.name}(this.transport, ${pathExpr});\n` +
            `}`,
        );
      } else {
        usesCollection = true;
        importedEntityTypes.add(child.type);
        importedEntityTypes.add(`${child.type}Input`);
        const foreignKeys = findForeignFieldsReferencing(child.entity, def.entity, entityContext);
        const inputType =
          foreignKeys.length > 0
            ? `NestedInput<${child.type}Input, ${foreignKeys.map(formatLiteral).join(' | ')}>`
            : `${child.type}Input`;
        methods.push(
          `${doc}${methodName}(${paramName}: string): Collection<${child.type}, ${inputType}> {\n` +
            `return new Collection<${child.type}, ${inputType}>(this.transport, ${pathExpr});\n` +
            `}`,
        );
      }
    }

    for (const [methodName, single] of Object.entries(def.single ?? {})) {
      const target = resources[single.resource];
      if (!target) {
        throw new Error(`Unknown single resource "${single.resource}" on "${resourceKey}"`);
      }
      templates.push(`/${def.path}/{}/${single.path}`);
      usesSingleton = true;
      usesSegment = true;
      importedEntityTypes.add(target.type);
      importedEntityTypes.add(`${target.type}Input`);

      const routeTemplate = `/${def.path}/{${paramName}}/${single.path}`;
      const pathExpr = `\`/${def.path}/\${segment(${paramName})}/${single.path}\``;
      const doc = formatJsDoc([`Related \`${single.path}\` singleton: \`${routeTemplate}\`.`]);
      methods.push(
        `${doc}${methodName}(${paramName}: string): Singleton<${target.type}, ${target.type}Input> {\n` +
          `return new Singleton<${target.type}, ${target.type}Input>(this.transport, ${pathExpr});\n` +
          `}`,
      );
    }

    const classDoc = formatJsDoc([`Admin API resource for \`/${def.path}\`.`]);
    const ctorDoc = formatJsDoc([`Creates the \`${className}\` bound to the given transport.`]);
    const bodyLines = [
      `${ctorDoc}constructor(transport: Transport) {\nsuper(transport, ${formatLiteral(`/${def.path}`)});\n}`,
      ...methods,
    ];
    classBlocks.push(
      `${classDoc}export class ${className} extends ${extendsClause} {\n${bodyLines.join('\n\n')}\n}\n`,
    );

    kongResourcesProps.push(
      `${formatJsDoc([`Resource endpoints under \`/${def.path}\`.`])}readonly ${resourceKey}: ${className};`,
    );
    kongResourcesInits.push(`this.${resourceKey} = new ${className}(transport);`);
  }

  const importLines = [];
  for (const mod of [...customClassImports.keys()].sort()) {
    const names = [...customClassImports.get(mod)].sort();
    importLines.push(`import { ${names.join(', ')} } from ${formatLiteral(mod)};`);
  }
  const resourceImports = [];
  if (usesCollection) {
    resourceImports.push('Collection');
  }
  if (usesSingleton) {
    resourceImports.push('Singleton');
  }
  if (resourceImports.length > 0) {
    importLines.push(`import { ${resourceImports.join(', ')} } from '../resource.js';`);
  }
  if (usesSegment) {
    importLines.push("import { segment, type Transport } from '../transport.js';");
  } else {
    importLines.push("import type { Transport } from '../transport.js';");
  }
  if (importedEntityTypes.size > 0) {
    const sortedTypes = [...importedEntityTypes].sort();
    importLines.push(`import type {\n${sortedTypes.join(',\n')},\n} from './entities.js';`);
  }

  const chunks = [
    GENERATED_BANNER,
    `${importLines.join('\n')}\n`,
    formatJsDoc([
      'Makes foreign-key fields referencing the parent resource optional on nested collection inputs.',
    ]) + 'export type NestedInput<I, K extends keyof I> = Omit<I, K> & Partial<Pick<I, K>>;\n',
    ...classBlocks,
    formatJsDoc(['Base class exposing all top-level Kong Admin API resource collections.']) +
      'export class KongResources {\n' +
      '/** HTTP transport used by resource collections. */\n' +
      'protected readonly transport: Transport;\n' +
      `${kongResourcesProps.join('\n')}\n\n` +
      '/** Creates all top-level resource collections bound to the given transport. */\n' +
      'constructor(transport: Transport) {\n' +
      'this.transport = transport;\n' +
      `${kongResourcesInits.join('\n')}\n` +
      '}\n' +
      '}\n',
    formatJsDoc([
      'Regular Admin API path templates served by the generated resource classes, with path parameters written as `{}`.',
    ]) +
      `export const RESOURCE_TEMPLATES: readonly string[] = [\n${templates.map(formatLiteral).join(',\n')},\n];\n`,
  ];

  return chunks.join('\n');
}

function collectSchemaPathsByType(node, targetType, currentPath, paths) {
  if (!isPlainObject(node)) {
    return;
  }
  if (node.type === targetType && currentPath) {
    paths.add(currentPath);
  }
  if (Array.isArray(node.fields)) {
    for (const entry of node.fields) {
      if (!isPlainObject(entry)) {
        continue;
      }
      for (const [fieldName, fieldDef] of Object.entries(entry)) {
        const nextPath = currentPath ? `${currentPath}.${fieldName}` : fieldName;
        collectSchemaPathsByType(fieldDef, targetType, nextPath, paths);
      }
    }
  }
  if ((node.type === 'array' || node.type === 'set') && isPlainObject(node.elements)) {
    const nextPath = currentPath ? `${currentPath}[]` : '[]';
    collectSchemaPathsByType(node.elements, targetType, nextPath, paths);
  }
  if (node.type === 'map' && isPlainObject(node.values)) {
    const nextPath = currentPath ? `${currentPath}.*` : '*';
    collectSchemaPathsByType(node.values, targetType, nextPath, paths);
  }
}

function buildMetaEntries(entityNames, entityContext, pluginRecords, targetType) {
  const entries = [];

  for (const entity of entityNames) {
    const paths = new Set();
    collectSchemaPathsByType(entityContext.schemas39.get(entity), targetType, '', paths);
    collectSchemaPathsByType(entityContext.schemas314.get(entity), targetType, '', paths);
    const sorted = [...paths].sort();
    entries.push(`${formatPropName(entity)}: [${sorted.map(formatLiteral).join(', ')}],`);
  }

  for (const plugin of pluginRecords) {
    const paths = new Set();
    collectSchemaPathsByType(plugin.config39, targetType, 'config', paths);
    collectSchemaPathsByType(plugin.config314, targetType, 'config', paths);
    const sorted = [...paths].sort();
    entries.push(
      `${formatPropName(`plugin:${plugin.name}`)}: [${sorted.map(formatLiteral).join(', ')}],`,
    );
  }

  return entries;
}

function generateMetaSource(resourcesJson, entityContext, pluginRecords) {
  const entityNames = [
    ...new Set(Object.values(resourcesJson.resources).map((resource) => resource.entity)),
  ].sort();

  const setEntries = buildMetaEntries(entityNames, entityContext, pluginRecords, 'set');
  const mapEntries = buildMetaEntries(entityNames, entityContext, pluginRecords, 'map');

  return (
    GENERATED_BANNER +
    formatJsDoc([
      'Paths of schema fields typed as `set` in Kong 3.9 or Kong Gateway 3.14, keyed by entity name and `plugin:<name>`.',
    ]) +
    `export const SET_FIELDS: Readonly<Record<string, readonly string[]>> = {\n${setEntries.join('\n')}\n};\n\n` +
    formatJsDoc([
      'Paths of schema fields typed as `map` in Kong 3.9 or Kong Gateway 3.14, keyed by entity name and `plugin:<name>`.',
    ]) +
    `export const MAP_FIELDS: Readonly<Record<string, readonly string[]>> = {\n${mapEntries.join('\n')}\n};\n`
  );
}

function renderTsValue(value) {
  if (value === null) {
    return 'null';
  }
  if (typeof value === 'string') {
    return formatLiteral(value);
  }
  if (typeof value === 'number' || typeof value === 'boolean') {
    return String(value);
  }
  if (Array.isArray(value)) {
    return `[${value.map(renderTsValue).join(', ')}]`;
  }
  if (isPlainObject(value)) {
    const entries = Object.entries(value).map(
      ([k, v]) => `${formatPropName(k)}: ${renderTsValue(v)}`,
    );
    return `{ ${entries.join(', ')} }`;
  }
  throw new Error(`Unsupported value in plugin-examples.json: ${typeof value}`);
}

function generatePluginExamplesSource(examplesJson, pluginRecords) {
  const entries = [];
  for (const plugin of pluginRecords) {
    const example = examplesJson.plugins[plugin.name];
    if (!example) {
      throw new Error(`Plugin "${plugin.name}" is missing from schemas/plugin-examples.json`);
    }
    const fields = [
      `config: ${renderTsValue(example.config)}`,
      `scope: ${formatLiteral(example.scope)}`,
      `update: { patch: ${renderTsValue(example.update.patch)}, field: ${formatLiteral(example.update.field)}, value: ${renderTsValue(example.update.value)} }`,
    ];
    if (example.only !== undefined) {
      fields.push(`only: ${renderTsValue(example.only)}`);
    }
    entries.push(`${formatPropName(plugin.name)}: {\n${fields.join(',\n')},\n}`);
  }

  return (
    GENERATED_BANNER +
    "import type { PluginConfigs, PluginName, PluginScopeName } from '../../src/generated/plugins.js';\n" +
    "import type { LiveTarget } from './live.js';\n\n" +
    '/** Small config update specification for a plugin example. */\n' +
    'export type PluginExampleUpdate<N extends PluginName> = N extends PluginName\n' +
    '  ? {\n' +
    '      [K in keyof PluginConfigs[N] & string]: {\n' +
    '        /** Partial config patch merged onto `config` for an update test. */\n' +
    '        patch: Partial<PluginConfigs[N]>;\n' +
    '        /** Top-level config field expected to match `value` after applying `patch`. */\n' +
    '        field: K;\n' +
    '        /** Expected value of `config[field]` after applying `patch`. */\n' +
    '        value: PluginConfigs[N][K];\n' +
    '      };\n' +
    '    }[keyof PluginConfigs[N] & string]\n' +
    '  : never;\n\n' +
    '/** Target-specific overrides for a plugin example when Kong 3.9 and 3.14 differ. */\n' +
    'export interface PluginExampleOverride<N extends PluginName> {\n' +
    '  config?: PluginConfigs[N];\n' +
    '  update?: PluginExampleUpdate<N>;\n' +
    '}\n\n' +
    '/** Validated example describing a minimal working configuration for plugin `N`. */\n' +
    'export interface PluginExample<N extends PluginName> {\n' +
    '  /** Minimal valid config accepted by Kong for plugin `N`. */\n' +
    '  config: PluginConfigs[N];\n' +
    '  /** Scope where tests attach this plugin, taken from `PLUGINS[N].scopes`. */\n' +
    '  scope: PluginScopeName;\n' +
    '  /** Small config change for an update test plus the field and value expected afterwards. */\n' +
    '  update: PluginExampleUpdate<N>;\n' +
    '  /** Target-specific overrides when a config or update differs between targets. */\n' +
    '  only?: Partial<Record<LiveTarget, PluginExampleOverride<N>>>;\n' +
    '}\n\n' +
    '/** Exhaustive map of plugin examples keyed by every first-class `PluginName`. */\n' +
    'export type PluginExamplesMap = {\n' +
    '  [N in PluginName]: PluginExample<N>;\n' +
    '};\n\n' +
    '/** Minimal valid plugin configs and updates generated from `schemas/plugin-examples.json`. */\n' +
    `export const PLUGIN_EXAMPLES = {\n${entries.join(',\n')},\n} satisfies PluginExamplesMap;\n\n` +
    '/** Sorted names of all first-class plugins covered by `PLUGIN_EXAMPLES`. */\n' +
    `export const PLUGIN_NAMES = [\n${[...pluginRecords.map((plugin) => plugin.name)].sort().map(formatLiteral).join(',\n')},\n] as const satisfies readonly PluginName[];\n`
  );
}

function escapeMarkdownCell(text) {
  return String(text).replace(/\r?\n/g, ' ').replace(/\s+/g, ' ').trim().replaceAll('|', '\\|');
}

function formatMarkdownCode(text) {
  const escaped = escapeMarkdownCell(text);
  if (escaped.includes('`')) {
    return `\`\` ${escaped} \`\``;
  }
  return `\`${escaped}\``;
}

function formatDocDefaultValue(value) {
  if (Array.isArray(value) && value.length > 0 && value.every((item) => isPlainObject(item))) {
    const serialized = JSON.stringify(value);
    if (serialized.length > 100) {
      return `${value.length} default items`;
    }
  }
  if (isPlainObject(value)) {
    const serialized = JSON.stringify(value);
    if (serialized.length > 100) {
      return 'object (see nested defaults)';
    }
  }
  return formatMarkdownCode(
    typeof value === 'string' ? formatLiteral(value) : JSON.stringify(value),
  );
}

function formatDocDefaultCell(def39, def314) {
  const has39 = hasNonNullDefault(def39);
  const has314 = hasNonNullDefault(def314);
  if (def39 && def314) {
    if (has39 && has314) {
      if (stableStringify(def39.default) === stableStringify(def314.default)) {
        return formatDocDefaultValue(def39.default);
      }
      return `${LABEL_39}: ${formatDocDefaultValue(def39.default)}; ${LABEL_314}: ${formatDocDefaultValue(def314.default)}`;
    }
    if (has39) {
      return `${LABEL_39}: ${formatDocDefaultValue(def39.default)}; ${LABEL_314}: none`;
    }
    if (has314) {
      return `${LABEL_39}: none; ${LABEL_314}: ${formatDocDefaultValue(def314.default)}`;
    }
    return '—';
  }
  if (has39) {
    return formatDocDefaultValue(def39.default);
  }
  if (has314) {
    return formatDocDefaultValue(def314.default);
  }
  return '—';
}

function formatDocTypeSingle(def39, def314, entityContext) {
  const sole = def39 ?? def314;
  const kongType = sole.type;

  switch (kongType) {
    case 'string': {
      const merged = mergeOneOf(def39?.one_of, def314?.one_of);
      if (merged && merged.values.length > 0) {
        return merged.values.map(formatLiteral).join(' | ');
      }
      return 'string';
    }
    case 'integer':
    case 'number': {
      const merged = mergeOneOf(def39?.one_of, def314?.one_of);
      if (merged && merged.values.length > 0) {
        return merged.values.map(formatLiteral).join(' | ');
      }
      return 'number';
    }
    case 'boolean':
      return 'boolean';
    case 'array':
    case 'set': {
      const elem39 = def39?.elements;
      const elem314 = def314?.elements;
      if (!elem39 && !elem314) {
        return 'Array<unknown>';
      }
      return `Array<${formatDocType(elem39, elem314, entityContext)}>`;
    }
    case 'map': {
      const val39 = def39?.values;
      const val314 = def314?.values;
      if (!val39 && !val314) {
        return 'Record<string, unknown>';
      }
      return `Record<string, ${formatDocType(val39, val314, entityContext)}>`;
    }
    case 'foreign': {
      const ref = def39?.reference ?? def314?.reference;
      return renderForeignAcceptedType(ref, entityContext);
    }
    case 'json':
      return 'unknown';
    case 'record': {
      if (isAbstractOrEmptyRecord(def39) && isAbstractOrEmptyRecord(def314)) {
        return 'Record<string, unknown>';
      }
      return 'object';
    }
    default:
      return 'unknown';
  }
}

function formatDocType(def39, def314, entityContext) {
  const type39 = def39?.type;
  const type314 = def314?.type;
  if (type39 && type314 && type39 !== type314) {
    const t39 = formatDocTypeSingle(def39, undefined, entityContext);
    const t314 = formatDocTypeSingle(undefined, def314, entityContext);
    return t39 === t314 ? t39 : `${t39} | ${t314}`;
  }
  return formatDocTypeSingle(def39, def314, entityContext);
}

function buildDocDescriptionCell(def39, def314, options = {}) {
  const {
    isShorthand = false,
    only39Parent = false,
    only314Parent = false,
    pluginName = undefined,
  } = options;

  // Fields that exist only on 3.14 must have no description, only the target notice.
  if (only314Parent || (!def39 && def314)) {
    return `${LABEL_314} only.`;
  }

  const parts = [];
  if (def39?.description) {
    parts.push(escapeMarkdownCell(resolvePluginRelativeLinks(def39.description, pluginName)));
  }

  if (only39Parent || (def39 && !def314)) {
    parts.push(`${LABEL_39} only.`);
  }

  const oneOfNotes = [];
  collectNestedOneOfNotes(def39, def314, oneOfNotes);
  for (const note of oneOfNotes) {
    parts.push(escapeMarkdownCell(note));
  }

  if (def39?.deprecation) {
    const dep = def39.deprecation;
    if (isPlainObject(dep) && typeof dep.message === 'string' && dep.message.trim()) {
      parts.push(
        `Deprecated: ${escapeMarkdownCell(resolvePluginRelativeLinks(dep.message, pluginName))}`,
      );
    } else {
      parts.push('Deprecated.');
    }
  } else if (isShorthand && def39?.description?.toLowerCase().includes('deprecated')) {
    parts.push('Deprecated.');
  }

  return parts.length > 0
    ? parts
        .map((part, idx) => (idx === parts.length - 1 || /[.!?]$/.test(part) ? part : `${part}.`))
        .join(' ')
    : '—';
}

function collectDocFieldRows(
  rec39,
  rec314,
  prefix,
  rows,
  entityContext,
  parentState = { only39: false, only314: false, insideSingleTarget: false, pluginName: undefined },
) {
  const regularFields = mergeFieldMaps(rec39?.fields, rec314?.fields);
  const regularNames = new Set(regularFields.map((f) => f.name));

  for (const { name, def39, def314 } of regularFields) {
    const fieldPath = prefix ? `${prefix}${name}` : name;
    const only39 = parentState.only39 || (def39 !== undefined && def314 === undefined);
    const only314 = parentState.only314 || (def39 === undefined && def314 !== undefined);
    const insideSingleTarget = parentState.insideSingleTarget || only39 || only314;

    const required = isRequiredInInput(def39, def314, parentState.insideSingleTarget);
    const typeText = formatDocType(def39, def314, entityContext);
    const defaultText = formatDocDefaultCell(def39, def314);
    const descriptionText = buildDocDescriptionCell(def39, def314, {
      only39Parent: parentState.only39,
      only314Parent: parentState.only314,
      pluginName: parentState.pluginName,
    });

    rows.push({
      field: formatMarkdownCode(fieldPath),
      type: formatMarkdownCode(typeText),
      required: required ? 'Yes' : 'No',
      defaultVal: defaultText,
      description: descriptionText,
    });

    const soleType = (def39 ?? def314)?.type;
    if (
      soleType === 'record' &&
      !(isAbstractOrEmptyRecord(def39) && isAbstractOrEmptyRecord(def314))
    ) {
      collectDocFieldRows(def39, def314, `${fieldPath}.`, rows, entityContext, {
        only39,
        only314,
        insideSingleTarget,
        pluginName: parentState.pluginName,
      });
    } else if (soleType === 'array' || soleType === 'set') {
      const elem39 = def39?.elements;
      const elem314 = def314?.elements;
      const elemType = (elem39 ?? elem314)?.type;
      if (
        elemType === 'record' &&
        !(isAbstractOrEmptyRecord(elem39) && isAbstractOrEmptyRecord(elem314))
      ) {
        collectDocFieldRows(elem39, elem314, `${fieldPath}[].`, rows, entityContext, {
          only39,
          only314,
          insideSingleTarget,
          pluginName: parentState.pluginName,
        });
      }
    } else if (soleType === 'map') {
      const val39 = def39?.values;
      const val314 = def314?.values;
      const valType = (val39 ?? val314)?.type;
      if (
        valType === 'record' &&
        !(isAbstractOrEmptyRecord(val39) && isAbstractOrEmptyRecord(val314))
      ) {
        collectDocFieldRows(val39, val314, `${fieldPath}.*.`, rows, entityContext, {
          only39,
          only314,
          insideSingleTarget,
          pluginName: parentState.pluginName,
        });
      }
    }
  }

  const shorthandFields = mergeFieldMaps(rec39?.shorthand_fields, rec314?.shorthand_fields);
  for (const { name, def39, def314 } of shorthandFields) {
    if (regularNames.has(name)) {
      continue;
    }
    const fieldPath = prefix ? `${prefix}${name}` : name;
    const only39 = parentState.only39 || (def39 !== undefined && def314 === undefined);
    const only314 = parentState.only314 || (def39 === undefined && def314 !== undefined);

    rows.push({
      field: formatMarkdownCode(fieldPath),
      type: formatMarkdownCode(formatDocType(def39, def314, entityContext)),
      required: 'No',
      defaultVal: formatDocDefaultCell(def39, def314),
      description: buildDocDescriptionCell(def39, def314, {
        isShorthand: true,
        only39Parent: parentState.only39 || only39,
        only314Parent: parentState.only314 || only314,
        pluginName: parentState.pluginName,
      }),
    });
  }
}

async function generatePluginPageSource(plugin, example, entityContext, prettierConfig) {
  const isGlobalOnly = plugin.scopes.length === 1 && plugin.scopes[0] === 'global';
  const enableOptionsParts = [];
  if (!isGlobalOnly) {
    enableOptionsParts.push("on: { route: 'my-route' }");
  }
  enableOptionsParts.push(`config: ${renderTsValue(example.config)}`);

  const rawExampleTs =
    "import { Kong } from 'kong-api-client';\n\n" +
    "const kong = new Kong({ adminUrl: 'http://localhost:8001' });\n\n" +
    `await kong.plugins.enable(${formatLiteral(plugin.name)}, {\n${enableOptionsParts.join(',\n')},\n});\n`;

  const formattedExampleTs = (
    await prettier.format(rawExampleTs, {
      ...prettierConfig,
      parser: 'typescript',
    })
  ).trimEnd();

  const rows = [];
  collectDocFieldRows(plugin.config39, plugin.config314, '', rows, entityContext, {
    only39: false,
    only314: false,
    insideSingleTarget: false,
    pluginName: plugin.name,
  });

  const tableLines = [
    '| Field | Type | Required | Default | Description |',
    '| --- | --- | --- | --- | --- |',
    ...rows.map(
      (row) =>
        `| ${row.field} | ${row.type} | ${row.required} | ${row.defaultVal} | ${row.description} |`,
    ),
  ];

  const kongUrl = `https://developer.konghq.com/plugins/${plugin.name}/`;
  const frontMatterTitle = /[:#[\]{}&*!|>'"%@`]/.test(plugin.title)
    ? JSON.stringify(plugin.title)
    : plugin.title;

  return (
    `---\ntitle: ${frontMatterTitle}\ngroup: Plugins\ncategory: ${plugin.category}\n---\n\n` +
    `# ${plugin.title} (\`${plugin.name}\`)\n\n` +
    `- **Category:** ${plugin.category}\n` +
    `- **Kong documentation:** [${kongUrl}](${kongUrl})\n` +
    `- **Targets:** ${plugin.targets.map((t) => `\`${t}\``).join(', ')}\n` +
    `- **Scopes:** ${plugin.scopes.map((s) => `\`${s}\``).join(', ')}\n` +
    `- **Protocols:** ${plugin.protocols.map((p) => `\`${p}\``).join(', ')}\n\n` +
    '## Example\n\n' +
    `\`\`\`ts\n${formattedExampleTs}\n\`\`\`\n\n` +
    '## Configuration fields\n\n' +
    `${tableLines.join('\n')}\n`
  );
}

function generatePluginsIndexSource(pluginRecords) {
  const byCategory = new Map();
  for (const plugin of pluginRecords) {
    let list = byCategory.get(plugin.category);
    if (!list) {
      list = [];
      byCategory.set(plugin.category, list);
    }
    list.push(plugin);
  }

  const sections = [];
  for (const category of [...byCategory.keys()].sort()) {
    const plugins = byCategory.get(category);
    const lines = [
      `## ${category}`,
      '',
      '| Plugin | Name | Scopes | Targets |',
      '| --- | --- | --- | --- |',
    ];
    for (const plugin of plugins) {
      const link = `./${plugin.categorySlug}/${plugin.name}.md`;
      lines.push(
        `| [${plugin.title}](${link}) | \`${plugin.name}\` | ${plugin.scopes.map((s) => `\`${s}\``).join(', ')} | ${plugin.targets.map((t) => `\`${t}\``).join(', ')} |`,
      );
    }
    sections.push(lines.join('\n'));
  }

  return (
    '---\ntitle: All Plugins\ngroup: Plugins\ncategory: Overview\n---\n\n' +
    '# Plugins\n\n' +
    `Reference pages for all ${pluginRecords.length} first-class Kong Gateway plugins supported by \`kong-api-client\`, grouped by category.\n\n` +
    `${sections.join('\n\n')}\n`
  );
}

function normalizeEndpointTemplate(endpoint) {
  return endpoint.replace(/\{[^/}]+\}/g, '{}');
}

function splitTopLevelCalls(callStr) {
  const parts = [];
  let current = '';
  let depth = 0;
  let quote = null;

  for (let i = 0; i < callStr.length; i += 1) {
    const ch = callStr[i];
    if (quote !== null) {
      current += ch;
      if (ch === '\\' && i + 1 < callStr.length) {
        current += callStr[i + 1];
        i += 1;
      } else if (ch === quote) {
        quote = null;
      }
      continue;
    }

    if (ch === "'" || ch === '"') {
      quote = ch;
      current += ch;
      continue;
    }
    if (ch === '(') {
      depth += 1;
      current += ch;
      continue;
    }
    if (ch === ')') {
      depth -= 1;
      current += ch;
      continue;
    }
    if (ch === ',' && depth === 0) {
      const trimmed = current.trim();
      if (!trimmed) {
        throw new Error(`Empty call segment in "${callStr}"`);
      }
      parts.push(trimmed);
      current = '';
      continue;
    }
    current += ch;
  }

  const tail = current.trim();
  if (tail) {
    parts.push(tail);
  }
  return parts;
}

function buildEndpointCoverageData(
  resourcesJson,
  endpointsJson,
  endpointNotesJson,
  endpoints39,
  endpoints314,
) {
  const recorded39ByNorm = new Map();
  for (const endpoint of endpoints39) {
    recorded39ByNorm.set(normalizeEndpointTemplate(endpoint), endpoint);
  }
  const recorded314NormSet = new Set(endpoints314.map(normalizeEndpointTemplate));

  const notesEntries = endpointNotesJson.notes ?? {};
  const usedNoteKeys = new Set();
  const getNote = (method, normalized) => {
    const opKey = `${method} ${normalized}`;
    if (Object.prototype.hasOwnProperty.call(notesEntries, opKey)) {
      usedNoteKeys.add(opKey);
      return notesEntries[opKey];
    }
    return undefined;
  };

  const resources = resourcesJson.resources;
  const resourceSections = [];
  const regularEndpoints = new Set();
  let regularOpCount = 0;

  for (const [resourceKey, def] of Object.entries(resources)) {
    if (def.topLevel === false) {
      continue;
    }

    const paramName = lowerCamel(def.type);
    const groups = [];

    const topCollectionPath = `/${def.path}`;
    const topItemDisplay = `/${def.path}/{${paramName}}`;
    const topItemNorm = `/${def.path}/{}`;
    const topReceiver = `kong.${resourceKey}`;
    const topRows = [
      {
        endpoint: topCollectionPath,
        normalized: topCollectionPath,
        method: 'GET',
        call: `${topReceiver}.list()`,
        note: getNote('GET', topCollectionPath),
      },
      {
        endpoint: topCollectionPath,
        normalized: topCollectionPath,
        method: 'POST',
        call: `${topReceiver}.create(input)`,
        note: getNote('POST', topCollectionPath),
      },
      {
        endpoint: topItemDisplay,
        normalized: topItemNorm,
        method: 'GET',
        call: `${topReceiver}.get(key)`,
        note: getNote('GET', topItemNorm),
      },
      {
        endpoint: topItemDisplay,
        normalized: topItemNorm,
        method: 'PATCH',
        call: `${topReceiver}.update(key, patch)`,
        note: getNote('PATCH', topItemNorm),
      },
      {
        endpoint: topItemDisplay,
        normalized: topItemNorm,
        method: 'PUT',
        call: `${topReceiver}.upsert(key, input)`,
        note: getNote('PUT', topItemNorm),
      },
      {
        endpoint: topItemDisplay,
        normalized: topItemNorm,
        method: 'DELETE',
        call: `${topReceiver}.delete(key)`,
        note: getNote('DELETE', topItemNorm),
      },
    ];
    groups.push({
      kind: 'collection',
      type: def.type,
      parentParam: null,
      rows: topRows,
    });

    for (const [methodName, nested] of Object.entries(def.nested ?? {})) {
      const child = resources[nested.resource];
      if (!child) {
        throw new Error(`Unknown nested resource "${nested.resource}" on "${resourceKey}"`);
      }
      const childParam = lowerCamel(child.type);
      const colDisplay = `/${def.path}/{${paramName}}/${nested.path}`;
      const colNorm = `/${def.path}/{}/${nested.path}`;
      const itemDisplay = `${colDisplay}/{${childParam}}`;
      const itemNorm = `${colNorm}/{}`;
      const receiver = `kong.${resourceKey}.${methodName}(${paramName})`;

      groups.push({
        kind: 'collection',
        type: child.type,
        parentParam: paramName,
        rows: [
          {
            endpoint: colDisplay,
            normalized: colNorm,
            method: 'GET',
            call: `${receiver}.list()`,
            note: getNote('GET', colNorm),
          },
          {
            endpoint: colDisplay,
            normalized: colNorm,
            method: 'POST',
            call: `${receiver}.create(input)`,
            note: getNote('POST', colNorm),
          },
          {
            endpoint: itemDisplay,
            normalized: itemNorm,
            method: 'GET',
            call: `${receiver}.get(key)`,
            note: getNote('GET', itemNorm),
          },
          {
            endpoint: itemDisplay,
            normalized: itemNorm,
            method: 'PATCH',
            call: `${receiver}.update(key, patch)`,
            note: getNote('PATCH', itemNorm),
          },
          {
            endpoint: itemDisplay,
            normalized: itemNorm,
            method: 'PUT',
            call: `${receiver}.upsert(key, input)`,
            note: getNote('PUT', itemNorm),
          },
          {
            endpoint: itemDisplay,
            normalized: itemNorm,
            method: 'DELETE',
            call: `${receiver}.delete(key)`,
            note: getNote('DELETE', itemNorm),
          },
        ],
      });
    }

    for (const [methodName, single] of Object.entries(def.single ?? {})) {
      const target = resources[single.resource];
      if (!target) {
        throw new Error(`Unknown single resource "${single.resource}" on "${resourceKey}"`);
      }
      const singleDisplay = `/${def.path}/{${paramName}}/${single.path}`;
      const singleNorm = `/${def.path}/{}/${single.path}`;
      const receiver = `kong.${resourceKey}.${methodName}(${paramName})`;

      groups.push({
        kind: 'singleton',
        type: target.type,
        parentParam: paramName,
        rows: [
          {
            endpoint: singleDisplay,
            normalized: singleNorm,
            method: 'GET',
            call: `${receiver}.get()`,
            note: getNote('GET', singleNorm),
          },
          {
            endpoint: singleDisplay,
            normalized: singleNorm,
            method: 'PATCH',
            call: `${receiver}.update(patch)`,
            note: getNote('PATCH', singleNorm),
          },
          {
            endpoint: singleDisplay,
            normalized: singleNorm,
            method: 'PUT',
            call: `${receiver}.upsert(input)`,
            note: getNote('PUT', singleNorm),
          },
        ],
      });
    }

    const sectionRows = groups.flatMap((group) => group.rows);
    for (const row of sectionRows) {
      regularEndpoints.add(row.normalized);
    }
    regularOpCount += sectionRows.length;

    resourceSections.push({
      resourceKey,
      path: def.path,
      groups,
      rows: sectionRows,
    });
  }

  const specialRows = [];
  const specialEndpoints = new Set();
  for (const [normTemplate, spec] of Object.entries(endpointsJson.special)) {
    const displayPath = recorded39ByNorm.get(normTemplate) ?? normTemplate;
    const calls = splitTopLevelCalls(spec.call);
    if (calls.length !== spec.methods.length) {
      throw new Error(
        `Special endpoint "${normTemplate}" has ${spec.methods.length} methods but ${calls.length} calls in schemas/endpoints.json`,
      );
    }
    specialEndpoints.add(normTemplate);
    for (let i = 0; i < spec.methods.length; i += 1) {
      const method = spec.methods[i];
      specialRows.push({
        endpoint: displayPath,
        normalized: normTemplate,
        method,
        call: calls[i],
        note: getNote(method, normTemplate),
      });
    }
  }

  const excludedRows = [];
  for (const [normTemplate, reason] of Object.entries(endpointsJson.excluded)) {
    const displayPath = recorded39ByNorm.get(normTemplate) ?? normTemplate;
    excludedRows.push({
      endpoint: displayPath,
      normalized: normTemplate,
      reason,
    });
  }

  const unusedNotes = Object.keys(notesEntries).filter((k) => !usedNoteKeys.has(k));
  if (unusedNotes.length > 0) {
    throw new Error(
      `Unused operation notes in schemas/endpoint-notes.json: ${unusedNotes.join(', ')}`,
    );
  }

  const servedEndpoints = new Set([...regularEndpoints, ...specialEndpoints]);
  const servedOn314Count = [...servedEndpoints].filter((ep) => recorded314NormSet.has(ep)).length;

  return {
    resourceSections,
    specialRows,
    excludedRows,
    counts: {
      recorded39Count: endpoints39.length,
      regularEndpointCount: regularEndpoints.size,
      specialEndpointCount: specialEndpoints.size,
      servedEndpointCount: servedEndpoints.size,
      servedOn314Count,
      regularOpCount,
      specialOpCount: specialRows.length,
      totalOpCount: regularOpCount + specialRows.length,
      excludedEndpointCount: excludedRows.length,
    },
  };
}

function renderOperationTable(rows) {
  const lines = [
    '| Endpoint | Method | Call | Notes |',
    '| --- | --- | --- | --- |',
    ...rows.map((row) => {
      const noteCell = row.note ? escapeMarkdownCell(row.note) : '—';
      return `| ${formatMarkdownCode(row.endpoint)} | ${formatMarkdownCode(row.method)} | ${formatMarkdownCode(row.call)} | ${noteCell} |`;
    }),
  ];
  return lines.join('\n');
}

function generateEndpointsPageSource(coverageData) {
  const { counts, resourceSections, specialRows, excludedRows } = coverageData;

  const resourceBlocks = resourceSections.map(
    (section) =>
      `### \`kong.${section.resourceKey}\` (\`/${section.path}\`)\n\n${renderOperationTable(section.rows)}`,
  );

  const excludedLines = [
    '| Endpoint | Reason |',
    '| --- | --- |',
    ...excludedRows.map(
      (row) => `| ${formatMarkdownCode(row.endpoint)} | ${escapeMarkdownCell(row.reason)} |`,
    ),
  ];

  return (
    '---\ntitle: Endpoint Coverage\ngroup: Guides\n---\n\n' +
    '# Endpoint Coverage\n\n' +
    `\`kong-api-client\` accounts for all **${counts.recorded39Count}** Admin API endpoints recorded on Kong 3.9: ` +
    `**${counts.servedEndpointCount}** are served through **${counts.totalOpCount}** typed operations ` +
    `(**${counts.regularOpCount}** across **${counts.regularEndpointCount}** regular resource endpoints and ` +
    `**${counts.specialOpCount}** across **${counts.specialEndpointCount}** special endpoints — ` +
    `all **${counts.servedOn314Count}** also present on Kong Gateway 3.14), ` +
    `and **${counts.excludedEndpointCount}** are excluded.\n\n` +
    '## Resources\n\n' +
    `${resourceBlocks.join('\n\n')}\n\n` +
    '## Special endpoints\n\n' +
    `${renderOperationTable(specialRows)}\n\n` +
    '## Excluded endpoints\n\n' +
    `${excludedLines.join('\n')}\n`
  );
}

const SPECIAL_CALL_PLACEHOLDERS = [
  ['tag', 'const tag = placeholder;'],
  ['key', 'const key = placeholder;'],
  ['config', 'const config: Record<string, unknown> = {};'],
  ['level', "const level: LogLevel = 'info';"],
  ['name', 'const name = placeholder;'],
  ['body', 'const body: unknown = {};'],
  ['upstream', 'const upstream = placeholder;'],
  ['target', 'const target = placeholder;'],
  ['address', 'const address = placeholder;'],
  ['host', 'const host = placeholder;'],
  ['cacheKey', 'const cacheKey = placeholder;'],
  ['pluginId', 'const pluginId = placeholder;'],
];

function generateEndpointCallsSource(coverageData) {
  const inputTypes = new Set();
  for (const section of coverageData.resourceSections) {
    for (const group of section.groups) {
      inputTypes.add(group.type);
    }
  }
  const sortedTypes = [...inputTypes].sort();

  const specialSource = coverageData.specialRows.map((row) => row.call).join('\n');
  const activeSpecialPlaceholders = SPECIAL_CALL_PLACEHOLDERS.filter(([ident]) =>
    new RegExp(`\\b${ident}\\b`).test(specialSource),
  );
  const usesLogLevel = activeSpecialPlaceholders.some(([ident]) => ident === 'level');

  const typeImports = [
    'Kong',
    ...(usesLogLevel ? ['LogLevel'] : []),
    'Patch',
    ...sortedTypes.map((typeName) => `${typeName}Input`),
  ];

  const inputInterfaceFields = sortedTypes.flatMap((typeName) => [
    `${typeName}: ${typeName}Input;`,
    `${typeName}Patch: Patch<${typeName}Input>;`,
  ]);

  const bodyBlocks = [];
  for (const section of coverageData.resourceSections) {
    for (const group of section.groups) {
      const decls = [];
      if (group.parentParam) {
        decls.push(`const ${group.parentParam} = placeholder;`);
      }
      if (group.kind === 'collection' && group.parentParam !== 'key') {
        decls.push('const key = placeholder;');
      }
      decls.push(`const input = inputs.${group.type};`);
      decls.push(`const patch = inputs.${group.type}Patch;`);
      const statements = group.rows.map((row) => `await ${row.call};`);
      bodyBlocks.push(`{\n${decls.join('\n')}\n${statements.join('\n')}\n}`);
    }
  }

  const specialDecls = activeSpecialPlaceholders.map(([, decl]) => decl);
  const specialStatements = coverageData.specialRows.map((row) => `await ${row.call};`);
  bodyBlocks.push(`{\n${specialDecls.join('\n')}\n${specialStatements.join('\n')}\n}`);

  return (
    GENERATED_BANNER +
    `import type {\n${typeImports.join(',\n')},\n} from '../../src/index.js';\n\n` +
    '/** Typed placeholder inputs used to compile every endpoint call documented in `docs/endpoints.md`. */\n' +
    `export interface EndpointCallInputs {\n${inputInterfaceFields.join('\n')}\n}\n\n` +
    '/**\n' +
    ' * Compile-time verification of every call expression listed in `docs/endpoints.md`.\n' +
    ' * Not invoked at run time.\n' +
    ' */\n' +
    'export async function verifyEndpointCalls(\n' +
    '  kong: Kong,\n' +
    '  placeholder: string,\n' +
    '  inputs: EndpointCallInputs,\n' +
    '): Promise<void> {\n' +
    `${bodyBlocks.join('\n\n')}\n` +
    '}\n'
  );
}

async function main() {
  const args = process.argv.slice(2);
  const checkOnly = args.includes('--check');
  const unknownArgs = args.filter((arg) => arg !== '--check');
  if (unknownArgs.length > 0) {
    throw new Error(`Unknown arguments: ${unknownArgs.join(', ')}`);
  }

  const prettierConfig = await readJson(path.join(REPO_ROOT, '.prettierrc.json'));
  const resourcesJson = await readJson(path.join(REPO_ROOT, 'schemas', 'resources.json'));
  const endpointsJson = await readJson(path.join(REPO_ROOT, 'schemas', 'endpoints.json'));
  const endpointNotesJson = await readJson(path.join(REPO_ROOT, 'schemas', 'endpoint-notes.json'));
  const endpoints39 = await readJson(path.join(REPO_ROOT, 'schemas', TARGET_39, 'endpoints.json'));
  const endpoints314 = await readJson(
    path.join(REPO_ROOT, 'schemas', TARGET_314, 'endpoints.json'),
  );
  const examplesJson = await readJson(path.join(REPO_ROOT, 'schemas', 'plugin-examples.json'));
  const entityContext = await loadEntityContext(resourcesJson);
  const pluginRecords = await loadPluginRecords();
  const endpointCoverage = buildEndpointCoverageData(
    resourcesJson,
    endpointsJson,
    endpointNotesJson,
    endpoints39,
    endpoints314,
  );

  const outputs = [
    {
      relPath: 'src/generated/plugins.ts',
      raw: generatePluginsSource(pluginRecords, entityContext),
    },
    {
      relPath: 'src/generated/entities.ts',
      raw: generateEntitiesSource(resourcesJson, entityContext),
    },
    {
      relPath: 'src/generated/resources.ts',
      raw: generateResourcesSource(resourcesJson, entityContext),
    },
    {
      relPath: 'src/generated/meta.ts',
      raw: generateMetaSource(resourcesJson, entityContext, pluginRecords),
    },
    {
      relPath: 'test/support/plugin-examples.ts',
      raw: generatePluginExamplesSource(examplesJson, pluginRecords),
    },
    {
      relPath: 'test/support/endpoint-calls.ts',
      raw: generateEndpointCallsSource(endpointCoverage),
    },
    {
      relPath: 'docs/endpoints.md',
      raw: generateEndpointsPageSource(endpointCoverage),
    },
    {
      relPath: 'docs/plugins/index.md',
      raw: generatePluginsIndexSource(pluginRecords),
    },
  ];

  for (const plugin of pluginRecords) {
    const example = examplesJson.plugins[plugin.name];
    if (!example) {
      throw new Error(`Plugin "${plugin.name}" is missing from schemas/plugin-examples.json`);
    }
    outputs.push({
      relPath: `docs/plugins/${plugin.categorySlug}/${plugin.name}.md`,
      raw: await generatePluginPageSource(plugin, example, entityContext, prettierConfig),
    });
  }

  const expectedDocPaths = new Set(
    outputs.filter((item) => item.relPath.startsWith('docs/plugins/')).map((item) => item.relPath),
  );
  const existingDocFiles = (await listFilesRecursive(path.join(REPO_ROOT, 'docs', 'plugins'))).map(
    (rel) => `docs/plugins/${rel}`,
  );
  const staleDocFiles = existingDocFiles.filter((rel) => !expectedDocPaths.has(rel));

  const mismatched = [];
  for (const item of outputs) {
    const absPath = path.join(REPO_ROOT, item.relPath);
    const formatted = await prettier.format(item.raw, {
      ...prettierConfig,
      filepath: absPath,
    });

    if (checkOnly) {
      let existing = null;
      try {
        existing = await readFile(absPath, 'utf8');
      } catch (err) {
        if (!(err && typeof err === 'object' && 'code' in err && err.code === 'ENOENT')) {
          throw err;
        }
      }
      if (existing !== formatted) {
        mismatched.push(item.relPath);
      }
    } else {
      await mkdir(path.dirname(absPath), { recursive: true });
      await writeFile(absPath, formatted, 'utf8');
    }
  }

  if (checkOnly) {
    const problems = [...mismatched, ...staleDocFiles.map((rel) => `${rel} (unexpected file)`)];
    if (problems.length > 0) {
      console.error('Generated files are out of date:');
      for (const relPath of problems) {
        console.error(`  - ${relPath}`);
      }
      process.exit(1);
    }
    console.log(`Generated files are up to date (${outputs.length} files).`);
  } else {
    for (const stale of staleDocFiles) {
      await rm(path.join(REPO_ROOT, stale), { force: true });
    }
    console.log(`Generated ${outputs.length} files.`);
  }
}

main().catch((err) => {
  console.error(err instanceof Error ? err.message : String(err));
  process.exit(1);
});
